    setVerifyBusy(true);
    try {
      const r = await fetch(`/api/redeem-verify?code=${encodeURIComponent(code)}`);
      const d = await r.json().catch(() => ({}));
      setVerifyResult(r.ok ? d : { status: d.status || 'not_found', error: d.error });
    } catch { setVerifyResult({ status: 'error' }); }
